  1	import {
  2	  DefaultColorThemePalette,
  3	  Editor,
  4	  TLShapeId,
  5	  createShapeId,
  6	} from "tldraw";
  7	import {
  8	  BaseDiscourseRelationUtil,
  9	  DISCOURSE_RELATION_SHAPE_TYPE,
 10	  DiscourseRelationShape,
 11	  getRelationColor,
 12	} from "~/components/canvas/DiscourseRelationShape/DiscourseRelationUtil";
 13	import { createOrUpdateArrowBinding } from "~/components/canvas/DiscourseRelationShape/helpers";
 14	import { getDiscourseNodeTypeId } from "~/components/canvas/DiscourseNodeUtil";
 15	import {
 16	  checkConnectionType,
 17	  getCreatableRelations,
 18	  isDiscourseNodeShape,
 19	} from "~/components/canvas/canvasUtils";
 20	import type { DiscourseRelation } from "~/utils/getDiscourseRelations";
 21	import { isRelationComplete } from "~/utils/isRelationComplete";
 22	
 23	type RelationTypeOption = { id: string; label: string; color: string };
 24	
 25	type DirectionalRelation = Pick<
 26	  DiscourseRelation,
 27	  "label" | "complement" | "source" | "destination"
 28	>;
 29	
 30	export const getDirectionalRelationLabel = ({
 31	  relation,
 32	  sourceNodeType,
 33	  targetNodeType,
 34	}: {
 35	  relation: DirectionalRelation;
 36	  sourceNodeType: string;
 37	  targetNodeType: string;
 38	}): string => {
 39	  const { isReverse } = checkConnectionType(
 40	    relation,
 41	    sourceNodeType,
 42	    targetNodeType,
 43	  );
 44	  return isReverse && relation.complement
 45	    ? relation.complement
 46	    : relation.label;
 47	};
 48	
 49	export const persistRelationArrow = async ({
 50	  editor,
 51	  arrow,
 52	  targetId,
 53	}: {
 54	  editor: Editor;
 55	  arrow: DiscourseRelationShape;
 56	  targetId: TLShapeId;
 57	}): Promise<void> => {
 58	  const util = editor.getShapeUtil(arrow);
 59	  if (
 60	    util instanceof BaseDiscourseRelationUtil &&
 61	    "handleCreateRelationsInRoam" in util
 62	  ) {
 63	    type UtilWithRoamPersistence = BaseDiscourseRelationUtil & {
 64	      handleCreateRelationsInRoam: (args: {
 65	        arrow: DiscourseRelationShape;
 66	        targetId: TLShapeId;
 67	      }) => Promise<void>;
 68	    };
 69	    await (util as UtilWithRoamPersistence).handleCreateRelationsInRoam({
 70	      arrow,
 71	      targetId,
 72	    });
 73	  }
 74	};
 75	
 76	export const getValidRelationTypesBetween = (
 77	  editor: Editor,
 78	  startId: TLShapeId,
 79	  endId: TLShapeId,
 80	): RelationTypeOption[] => {
 81	  const startNode = editor.getShape(startId);
 82	  const endNode = editor.getShape(endId);
 83	  if (!startNode || !endNode) return [];
 84	  if (
 85	    !isDiscourseNodeShape(editor, startNode) ||
 86	    !isDiscourseNodeShape(editor, endNode)
 87	  )
 88	    return [];
 89	
 90	  const startNodeType = getDiscourseNodeTypeId({ shape: startNode });
 91	  const endNodeType = getDiscourseNodeTypeId({ shape: endNode });
 92	
 93	  const colorPalette = DefaultColorThemePalette.lightMode;
 94	  const validTypes: RelationTypeOption[] = [];
 95	  const seenLabels = new Set<string>();
 96	
 97	  for (const relation of getCreatableRelations()) {
 98	    if (!isRelationComplete(relation)) continue;
 99	    const { isDirect, isReverse } = checkConnectionType(
100	      relation,
101	      startNodeType,
102	      endNodeType,
103	    );
104	    if (!isDirect && !isReverse) continue;
105	
106	    const label = getDirectionalRelationLabel({
107	      relation,
108	      sourceNodeType: startNodeType,
109	      targetNodeType: endNodeType,
110	    });
111	    if (seenLabels.has(label)) continue;
112	    seenLabels.add(label);
113	
114	    const hexColor =
115	      colorPalette[getRelationColor(relation.label)]?.solid ?? "#333";
116	    validTypes.push({ id: relation.id, label, color: hexColor });
117	  }
118	
119	  return validTypes;
120	};
121	
122	export const createDefaultRelationBetweenNodes = async ({
123	  editor,
124	  relationId,
125	  sourceId,
126	  targetId,
127	}: {
128	  editor: Editor;
129	  relationId: string;
130	  sourceId: TLShapeId;
131	  targetId: TLShapeId;
132	}): Promise<TLShapeId | null> => {
133	  const selectedRelation = getCreatableRelations().find(
134	    (r) => r.id === relationId,
135	  );
136	  if (!selectedRelation) return null;
137	
138	  const sourceNode = editor.getShape(sourceId);
139	  const targetNode = editor.getShape(targetId);
140	  if (
141	    !sourceNode ||
142	    !targetNode ||
143	    !isDiscourseNodeShape(editor, sourceNode) ||
144	    !isDiscourseNodeShape(editor, targetNode)
145	  )
146	    return null;
147	  const label = getDirectionalRelationLabel({
148	    relation: selectedRelation,
149	    sourceNodeType: getDiscourseNodeTypeId({ shape: sourceNode }),
150	    targetNodeType: getDiscourseNodeTypeId({ shape: targetNode }),
151	  });
152	
153	  const sourceBounds = editor.getShapePageBounds(sourceId);
154	  if (!sourceBounds) return null;
155	
156	  const color = getRelationColor(selectedRelation.label);
157	  const arrowId = createShapeId();
158	  editor.createShape<DiscourseRelationShape>({
159	    id: arrowId,
160	    type: DISCOURSE_RELATION_SHAPE_TYPE,
161	    x: sourceBounds.midX,
162	    y: sourceBounds.midY,
163	    props: {
164	      color,
165	      labelColor: color,
166	      text: label,
167	      relationTypeId: relationId,
168	      dash: "draw",
169	      size: "m",
170	      fill: "none",
171	      bend: 0,
172	      start: { x: 0, y: 0 },
173	      end: { x: 0, y: 0 },
174	      arrowheadStart: "none",
175	      arrowheadEnd: "arrow",
176	      labelPosition: 0.5,
177	      font: "draw",
178	      scale: 1,
179	    },
180	  });
181	
182	  const newArrow = editor.getShape<DiscourseRelationShape>(arrowId);
183	  if (!newArrow) return null;
184	
185	  createOrUpdateArrowBinding(editor, newArrow, sourceId, {
186	    terminal: "start",
187	    normalizedAnchor: { x: 0.5, y: 0.5 },
188	    isPrecise: false,
189	    isExact: false,
190	  });
191	  createOrUpdateArrowBinding(editor, newArrow, targetId, {
192	    terminal: "end",
193	    normalizedAnchor: { x: 0.5, y: 0.5 },
194	    isPrecise: false,
195	    isExact: false,
196	  });
197	
198	  editor.select(arrowId);
199	
200	  await persistRelationArrow({ editor, arrow: newArrow, targetId });
201	
202	  // handleCreateRelationsInRoam deletes the new arrow if it rejects the
203	  // conversion, so a surviving shape means the relation was persisted.
204	  return editor.getShape(arrowId) ? arrowId : null;
205	};

  1	import React, { useCallback, useEffect, useMemo, useRef } from "react";
  2	import { TLShapeId, useEditor } from "tldraw";
  3	import { getValidRelationTypesBetween } from "./relationCreation";
  4	
  5	type RelationTypeDropdownProps = {
  6	  sourceId: TLShapeId;
  7	  targetId: TLShapeId;
  8	  dropdownPos: { x: number; y: number };
  9	  onSelect: (relationId: string) => void;
 10	  onDismiss: () => void;
 11	};
 12	
 13	export const RelationTypeDropdown = ({
 14	  sourceId,
 15	  targetId,
 16	  dropdownPos,
 17	  onSelect,
 18	  onDismiss,
 19	}: RelationTypeDropdownProps) => {
 20	  const editor = useEditor();
 21	  const dropdownRef = useRef<HTMLDivElement>(null);
 22	
 23	  const validRelationTypes = useMemo(
 24	    () => getValidRelationTypesBetween(editor, sourceId, targetId),
 25	    [editor, sourceId, targetId],
 26	  );
 27	
 28	  // Handle click outside
 29	  useEffect(() => {
 30	    const handlePointerDown = (e: PointerEvent) => {
 31	      if (
 32	        dropdownRef.current &&
 33	        !dropdownRef.current.contains(e.target as Node)
 34	      ) {
 35	        onDismiss();
 36	      }
 37	    };
 38	
 39	    const timer = setTimeout(() => {
 40	      window.addEventListener("pointerdown", handlePointerDown, true);
 41	    }, 100);
 42	
 43	    return () => {
 44	      clearTimeout(timer);
 45	      window.removeEventListener("pointerdown", handlePointerDown, true);
 46	    };
 47	  }, [onDismiss]);
 48	
 49	  // Handle Escape key
 50	  useEffect(() => {
 51	    const handleKeyDown = (e: KeyboardEvent) => {
 52	      if (e.key === "Escape") {
 53	        onDismiss();
 54	      }
 55	    };
 56	    window.addEventListener("keydown", handleKeyDown, true);
 57	    return () => window.removeEventListener("keydown", handleKeyDown, true);
 58	  }, [onDismiss]);
 59	
 60	  const handleSelect = useCallback(
 61	    (relationId: string) => {
 62	      onSelect(relationId);
 63	    },
 64	    [onSelect],
 65	  );
 66	
 67	  if (validRelationTypes.length === 0) return null;
 68	
 69	  return (
 70	    <div
 71	      ref={dropdownRef}
 72	      style={{
 73	        position: "absolute",
 74	        left: `${dropdownPos.x}px`,
 75	        top: `${dropdownPos.y}px`,
 76	        transform: "translate(-50%, -50%)",
 77	        pointerEvents: "all",
 78	        zIndex: 30,
 79	      }}
 80	      onPointerDown={(e) => e.stopPropagation()}
 81	      onPointerUp={(e) => e.stopPropagation()}
 82	      onClick={(e) => e.stopPropagation()}
 83	    >
 84	      <div className="max-h-[240px] min-w-[160px] overflow-y-auto rounded-lg border border-gray-200 bg-white p-4 shadow-lg">
 85	        <div className="px-2 py-1 text-xs font-semibold uppercase tracking-wide text-gray-500">
 86	          Relation Type
 87	        </div>
 88	        {validRelationTypes.map((rt) => (
 89	          <button
 90	            key={rt.id}
 91	            onClick={() => handleSelect(rt.id)}
 92	            className="flex w-full cursor-pointer items-center gap-2 rounded-md border-none bg-transparent px-3 py-2 text-left text-[13px] text-[#333] hover:bg-[#f0f0f0]"
 93	            onMouseEnter={(e) => {
 94	              (e.currentTarget as HTMLElement).style.backgroundColor =
 95	                "#f0f0f0";
 96	            }}
 97	            onMouseLeave={(e) => {
 98	              (e.currentTarget as HTMLElement).style.backgroundColor =
 99	                "transparent";
100	            }}
101	          >
102	            <span
103	              style={{
104	                backgroundColor: rt.color,
105	              }}
106	              className="h-2 w-2 flex-shrink-0 rounded-full bg-[#333]"
107	            />
108	            {rt.label}
109	          </button>
110	        ))}
111	      </div>
112	    </div>
113	  );
114	};
