          return deleteAndWarn(
            `Target node must be of type ${uniqueTargetTexts.join(", ")}`,
          );
        }

        if (matchingRelation.id !== relationTypeId) {
          editor.updateShapes<DiscourseRelationShape>([
            {
              id: arrow.id,
              type: arrow.type,
              props: { relationTypeId: matchingRelation.id },
