export const createAllRelationShapeTools = (
  relationNames: string[],
): TLStateNodeConstructor[] => {
  return relationNames.map((name) => {
    class RelationShapeTool extends StateNode {
      static override initial = "idle";
      static override id = name;
      static override isLockable = true;
      static override children = (): TLStateNodeConstructor[] => [
        this.Idle,
        this.Pointing,
      ];

      override onEnter = () => {
        this.editor.setCursor({
          type: "cross",
        });
      };

      static Pointing = class extends StateNode {
        static override id = "pointing";
        shape?: DiscourseRelationShape;
        markId = "";

        cancelAndWarn = (title: string) => {
          dispatchToastEvent({
            id: `tldraw-cancel-and-warn-${title}`,
            title,
            severity: "warning",
          });
          this.cancel();
        };

        override onEnter = () => {
          this.didTimeout = false;

          const selectedRelations = (
            discourseContext.relations[name] || []
          ).filter(isAcceptedRelationSchema);
          const hasIncompleteSelectedRelation = selectedRelations.some(
            (relation) => !isRelationComplete(relation),
          );
          if (hasIncompleteSelectedRelation) {
            this.cancelAndWarn(
              "Relation type is incomplete. Set label, complement, source, and destination in settings.",
            );
            return;
          }

          const target = this.editor.getShapeAtPoint(
            this.editor.inputs.currentPagePoint,
            // {
            //   filter: (targetShape) => {
            //     return (
            //       !targetShape.isLocked &&
            //       this.editor.canBindShapes({
            //         fromShape: name,
            //         toShape: targetShape,
            //         binding: name,
            //       })
            //     );
            //   },
            //   margin: 0,
            //   hitInside: true,
            //   renderingOnly: true,
            // }
          );

          const targetNodeTypeId =
            target && isDiscourseNodeShape(target)
              ? getDiscourseNodeTypeId({ shape: target })
              : undefined;
          const relation = selectedRelations.find(
            (r) =>
              r.source === targetNodeTypeId ||
              r.destination === targetNodeTypeId,
          );
          if (relation) {
            this.shapeType = relation.id;
          } else {
            const acceptableTypes = selectedRelations
              .flatMap((r) => [
                discourseContext.nodes[r.source]?.text,
                discourseContext.nodes[r.destination]?.text,
              ])
              .filter(Boolean);
            const uniqueTypes = [...new Set(acceptableTypes)];
            this.cancelAndWarn(
              `Starting node must be one of ${uniqueTypes.join(", ")}`,
            );
            return;
          }
          if (!target) {
            this.createArrowShape();
          } else {
            this.editor.setHintingShapes([target.id]);
          }

          this.startPreciseTimeout();
        };

        override onExit = () => {
          this.shape = undefined;
          this.editor.setHintingShapes([]);
          this.clearPreciseTimeout();
        };

        override onPointerMove: TLEventHandlers["onPointerMove"] = () => {
          if (this.editor.inputs.isDragging) {
            if (!this.shape) {
              this.createArrowShape();
            }

            if (!this.shape) throw Error(`expected shape`);

            // const initialEndHandle = this.editor
            //   .getShapeHandles(this.shape)!
            //   .find((h) => h.id === "end")!;
            this.updateArrowShapeEndHandle();

            this.editor.setCurrentTool("select.dragging_handle", {
              shape: this.shape,
              handle: { id: "end", type: "vertex", index: "a3", x: 0, y: 0 },
              isCreating: true,
              onInteractionEnd: name,
            });
          }
        };

        override onPointerUp: TLEventHandlers["onPointerUp"] = () => {
          this.cancel();
        };

        override onCancel: TLEventHandlers["onCancel"] = () => {
          this.cancel();
        };

        override onComplete: TLEventHandlers["onComplete"] = () => {
          this.cancel();
        };

        override onInterrupt: TLEventHandlers["onInterrupt"] = () => {
          this.cancel();
        };

        cancel() {
          if (this.shape) {
            // the arrow might not have been created yet!
            this.editor.bailToMark(this.markId);
          }
          this.editor.setHintingShapes([]);
          this.parent.transition("idle");
        }

        createArrowShape() {
          const { originPagePoint } = this.editor.inputs;

          const id = createShapeId();

          this.markId = `creating:${id}`;
          this.editor.mark(this.markId);

          const color = getRelationColor(name);

          if (!this.shapeType) {
            this.cancelAndWarn("Must start on a node");
            return;
          }

          this.editor.createShape<DiscourseRelationShape>({
            id,
            type: DISCOURSE_RELATION_SHAPE_TYPE,
            x: originPagePoint.x,
            y: originPagePoint.y,
            props: {
              color,
              labelColor: color,
              text: name,
              relationTypeId: this.shapeType,
              scale: this.editor.user.getIsDynamicResizeMode()
                ? 1 / this.editor.getZoomLevel()
                : 1,

  const selectedShape = useValue(
    "selectedShape",
    () => editor.getOnlySelectedShape(),
    [editor],
  );
  const selectedShapes = useValue(
    "selectedShapes",
    () => editor.getSelectedShapes(),
    [editor],
  );
  const shareableResults = getShareableCanvasSelectionResults({
    shapes: selectedShapes,
  });
  const isTextSelected = selectedShape?.type === "text";
  const isImageSelected = selectedShape?.type === "image";
  const arrowRelationOptions = useValue(
    "arrowRelationOptions",
    () => {
      if (!selectedShape || selectedShape.type !== "arrow") return null;
      const boundNodes = getArrowBoundNodeInfo(editor, selectedShape);
      if (!boundNodes) return null;
      const relationTypes = getValidRelationTypesBetween(
        editor,
        boundNodes.startId,
        boundNodes.endId,
      );
      if (relationTypes.length === 0) return null;
      return { arrowId: selectedShape.id, ...boundNodes, relationTypes };
    },
    [editor, selectedShape],
  );

  return (
    <DefaultContextMenu>
      <DefaultContextMenuContent />
      {shareableResults.length > 0 && (
        <TldrawUiMenuGroup id="share-data-group">
          <TldrawUiMenuItem
            id="share-data"
            label="Share Data"
            readonlyOk
            onSelect={() => {
              const currentSelectedShapes = editor.getSelectedShapes();
              const currentResults = getShareableCanvasSelectionResults({
                shapes: currentSelectedShapes,
              });
              if (!currentResults.length) return;

              posthog.capture("Canvas: Share Data Clicked", {
                resultCount: currentResults.length,
                selectedShapeCount: currentSelectedShapes.length,
              });
              renderShareDataDialog({
                results: currentResults,
                isExportDiscourseGraph: true,
              });
            }}
          />
        </TldrawUiMenuGroup>
      )}
      {(isTextSelected || isImageSelected) && (
        <TldrawUiMenuGroup id="convert-to-group">
          <TldrawUiMenuSubmenu id="convert-to-submenu" label="Convert To">
            {allNodes
              // Page not yet supported: requires page-node to have image flag option
              .filter((node) => !(isImageSelected && node.type === "page-node"))
              .map((node) => {
                return (
                  <TldrawUiMenuItem
                    key={node.type}
                    id={`convert-to-${node.type}`}
                    label={node.text}
                    readonlyOk
                    onSelect={getOnSelectForShape({
                      shape: selectedShape,
                      nodeType: node.type,
                      editor,
                      extensionAPI,
                    })}
                  />
                );
              })}
          </TldrawUiMenuSubmenu>
        </TldrawUiMenuGroup>
      )}
      {arrowRelationOptions && (
        <TldrawUiMenuGroup id="relation-group">
          <TldrawUiMenuSubmenu id="relation-submenu" label="Relation">
            {arrowRelationOptions.relationTypes.map((rt) => (
              <TldrawUiMenuItem
                key={rt.id}
                id={`relation-${rt.id}`}
                label={rt.label}
                onSelect={async () => {
                  const arrow = editor.getShape<TLArrowShape>(
                    arrowRelationOptions.arrowId,
                  );
                  if (!arrow || arrow.type !== "arrow") return;

                  await convertArrowToRelation({
                    editor,
                    arrow,
                    relationId: rt.id,
                  });
                }}
              />
            ))}
          </TldrawUiMenuSubmenu>
        </TldrawUiMenuGroup>
      )}
    </DefaultContextMenu>
  );
};
